using Unity.Netcode;
using UnityEngine;

// Author : Baptiste Vu Liem
namespace Com.IsartDigital.GoobyrFPS.AI
{
    /// <summary>What an NPC blurts out (gibberish voices, generated by the SFX builder as <c>bark_&lt;voice&gt;_&lt;kind&gt;</c>).</summary>
    public enum Barks : byte
    {
        /// <summary>"Huh?" - something odd caught its eye or ear.</summary>
        Huh,
        /// <summary>"Hey!" - it confronts someone.</summary>
        Hey,
        /// <summary>"Over there!" - it spotted the player in a fight, or a witness points.</summary>
        OverThere,
        /// <summary>"Help!" - a civilian running.</summary>
        Help,
        /// <summary>A scream - a civilian startled by a gun, a shot, a body.</summary>
        Scream,
        /// <summary>"Clear." - a searcher giving up.</summary>
        Clear,
        /// <summary>Radio chatter - a guard calling it in.</summary>
        Radio,
        /// <summary>Small talk - a patrol pair, guests mingling.</summary>
        Chatter
    }

    /// <summary>
    /// Barks: short gibberish lines on state changes, rate-limited per NPC and across the map (a
    /// stampede is a few screams, not fifty). Every machine plays them at the head with the NPC's own
    /// voice; <see cref="LastBark"/> / <see cref="LastBarkTime"/> let the face animate the mouth.
    /// </summary>
    public partial class Npc
    {
        /// <summary>Every machine: the last thing this NPC said and when (Time.time), for its face.</summary>
        public Barks LastBark { get; private set; }
        public float LastBarkTime { get; private set; } = -100f;

        private float _nextBark;
        private static float _barkWindowStart;
        private static int _barksInWindow, _chatterInWindow;

        /// <summary>Host: say something, unless it spoke a moment ago or the map is already loud.</summary>
        private void Bark(Barks pBark)
        {
            if (!IsServer || !Health.IsAlive) return;
            if (Time.time < _nextBark && pBark != Barks.Scream) return;
            bool lChatter = pBark == Barks.Chatter;
            if (lChatter && !PlayerWithin(NpcRules.CHATTER_EARSHOT)) return;
            if (Time.time - _barkWindowStart > 1f || Time.time < _barkWindowStart) { _barkWindowStart = Time.time; _barksInWindow = 0; _chatterInWindow = 0; }
            if (!NpcRules.BarkAllowed(_barksInWindow, _chatterInWindow, lChatter)) return;
            _barksInWindow++;
            if (lChatter) _chatterInWindow++;
            _nextBark = Time.time + NpcRules.BarkGap(pBark);
            BarkRpc(pBark);
        }

        /// <summary>Is a living player within <paramref name="pRange"/> metres (anyone to hear it)?</summary>
        private bool PlayerWithin(float pRange)
        {
            foreach (Player.PlayerAvatar lPlayer in Player.PlayerAvatar.All)
                if (lPlayer != null && lPlayer.Health.IsAlive && (lPlayer.transform.position - transform.position).sqrMagnitude < pRange * pRange) return true;
            return false;
        }

        [Rpc(SendTo.Everyone)]
        private void BarkRpc(Barks pBark)
        {
            LastBark = pBark;
            LastBarkTime = Time.time;
            string lClip = "bark_" + NpcRules.VoiceOf(NetworkObjectId, IsCrowd) + "_" + pBark.ToString().ToLowerInvariant();
            float lRange = pBark == Barks.Scream ? 45f : pBark == Barks.Chatter ? 12f : 28f;
            Audio.Sfx.Play(lClip, Eye, pBark == Barks.Chatter ? 0.55f : 0.9f, lRange, 0.06f);
        }
    }
}
